package com.magicstudios.magiccore.phasesix;
import com.magicstudios.magiccore.modules.tools.*;import org.junit.jupiter.api.Test;import java.time.*;import java.util.*;import static org.assertj.core.api.Assertions.*;
class CustomToolServiceTest{
 @Test void plannerProducesBoundedFaceAwarePlaneAndCube(){ToolAreaPlanner planner=new ToolAreaPlanner();ToolBlockPosition origin=new ToolBlockPosition(10,64,10);var plane=planner.plan(origin,ToolAreaPlanner.Face.NORTH,new ToolUpgrade(1,ToolUpgrade.Shape.PLANE,1,1,1));assertThat(plane).hasSize(9);assertThat(plane).allMatch(value->value.z()==10);var tunnel=planner.plan(origin,ToolAreaPlanner.Face.NORTH,new ToolUpgrade(2,ToolUpgrade.Shape.CUBE,1,3,2));assertThat(tunnel).hasSize(27);assertThat(tunnel).extracting(ToolBlockPosition::z).containsExactlyInAnyOrderElementsOf(java.util.stream.IntStream.rangeClosed(10,12).boxed().flatMap(z->java.util.stream.Stream.generate(()->z).limit(9)).toList());}
 @Test void cooldownAndUpgradeDefinitionsAreCanonical(){ToolDefinition definition=new ToolDefinition("wild","NETHERITE_PICKAXE","Wild",100,Duration.ofSeconds(1),"VANILLA",Set.of("STONE"),List.of(new ToolUpgrade(1,ToolUpgrade.Shape.PLANE,1,1,1),new ToolUpgrade(2,ToolUpgrade.Shape.CUBE,1,2,2)));var service=new InMemoryCustomToolService(List.of(definition));UUID player=UUID.randomUUID();Instant now=Instant.parse("2026-08-11T12:00:00Z");assertThat(service.claimCooldown(player,"wild",now)).isTrue();assertThat(service.claimCooldown(player,"wild",now.plusMillis(999))).isFalse();assertThat(service.claimCooldown(player,"wild",now.plusSeconds(1))).isTrue();assertThat(service.require("wild").upgrade(2).dropMultiplier()).isEqualTo(2);assertThatThrownBy(()->service.require("wild").upgrade(3)).isInstanceOf(IllegalArgumentException.class);}
}
